  "{from} to {to}: {a} units a day, vs {b} a day from {c} to {d}": { es: "{from} a {to}: {a} unidades al día, frente a {b} al día del {c} al {d}", fr: "{from} au {to} : {a} unités par jour, contre {b} par jour du {c} au {d}", de: "{from} bis {to}: {a} Einheiten pro Tag, gegenüber {b} pro Tag vom {c} bis {d}", it: "Dal {from} al {to}: {a} unità al giorno, contro {b} al giorno dal {c} al {d}", pt: "{from} a {to}: {a} unidades por dia, face a {b} por dia de {c} a {d}", nl: "{from} tot {to}: {a} stuks per dag, tegenover {b} per dag van {c} tot {d}", pl: "Od {from} do {to}: {a} szt. dziennie, wobec {b} dziennie od {c} do {d}" },
  "Variants using their collection's own index: {n}": { es: "Variantes con el índice propio de su colección: {n}", fr: "Variantes utilisant l'indice de leur collection : {n}", de: "Varianten mit dem eigenen Index ihrer Kollektion: {n}", it: "Varianti che usano l'indice della propria collezione: {n}", pt: "Variantes com o índice da própria coleção: {n}", nl: "Varianten met de eigen index van hun collectie: {n}", pl: "Warianty z własnym indeksem kolekcji: {n}" },
  "Trend (last 28 days vs the same weeks last year): × {x}": { es: "Tendencia (últimos 28 días frente a las mismas semanas del año pasado): × {x}", fr: "Tendance (28 derniers jours contre les mêmes semaines l'an dernier) : × {x}", de: "Trend (letzte 28 Tage gegenüber denselben Wochen im Vorjahr): × {x}", it: "Tendenza (ultimi 28 giorni rispetto alle stesse settimane dell'anno scorso): × {x}", pt: "Tendência (últimos 28 dias face às mesmas semanas do ano passado): × {x}", nl: "Trend (laatste 28 dagen tegenover dezelfde weken vorig jaar): × {x}", pl: "Trend (ostatnie 28 dni wobec tych samych tygodni rok temu): × {x}" },
  "Based on: sales per day while in stock × seasonal index × trend × plan × {n} days, {range}": { es: "Basado en: ventas al día con stock × índice de temporada × tendencia × plan × {n} días, {range}", fr: "Basé sur : ventes par jour en stock × indice saisonnier × tendance × plan × {n} jours, {range}", de: "Basierend auf: Verkäufe pro Tag mit Bestand × Saisonindex × Trend × Plan × {n} Tage, {range}", it: "Basato su: vendite al giorno con stock × indice stagionale × tendenza × piano × {n} giorni, {range}", pt: "Baseado em: vendas por dia com stock × índice sazonal × tendência × plano × {n} dias, {range}", nl: "Gebaseerd op: verkopen per dag op voorraad × seizoensindex × trend × plan × {n} dagen, {range}", pl: "Na podstawie: sprzedaż dziennie przy dostępności × indeks sezonowy × trend × plan × {n} dni, {range}" },
  "Based on: sales per day while in stock × seasonal index × plan × {n} days, {range}": { es: "Basado en: ventas al día con stock × índice de temporada × plan × {n} días, {range}", fr: "Basé sur : ventes par jour en stock × indice saisonnier × plan × {n} jours, {range}", de: "Basierend auf: Verkäufe pro Tag mit Bestand × Saisonindex × Plan × {n} Tage, {range}", it: "Basato su: vendite al giorno con stock × indice stagionale × piano × {n} giorni, {range}", pt: "Baseado em: vendas por dia com stock × índice sazonal × plano × {n} dias, {range}", nl: "Gebaseerd op: verkopen per dag op voorraad × seizoensindex × plan × {n} dagen, {range}", pl: "Na podstawie: sprzedaż dziennie przy dostępności × indeks sezonowy × plan × {n} dni, {range}" },
