  "Variants without a price, not counted: {n}": { es: "Variantes sin precio, no contadas: {n}", fr: "Variantes sans prix, non comptées : {n}", de: "Varianten ohne Preis, nicht gezählt: {n}", it: "Varianti senza prezzo, non conteggiate: {n}", pt: "Variantes sem preço, não contadas: {n}", nl: "Varianten zonder prijs, niet meegeteld: {n}", pl: "Warianty bez ceny, nieliczone: {n}" },
  "Based on: expected units × each variant's price in Shopify": { es: "Basado en: unidades esperadas × precio de cada variante en Shopify", fr: "Basé sur : unités attendues × prix de chaque variante dans Shopify", de: "Basierend auf: erwartete Einheiten × Preis jeder Variante in Shopify", it: "Basato su: unità previste × prezzo di ogni variante in Shopify", pt: "Baseado em: unidades esperadas × preço de cada variante no Shopify", nl: "Gebaseerd op: verwachte stuks × prijs van elke variant in Shopify", pl: "Na podstawie: oczekiwane sztuki × cena każdego wariantu w Shopify" },
