  "Late — order now: {n}": { es: "Tarde, pide ya: {n}", fr: "En retard, commandez maintenant : {n}", de: "Zu spät – jetzt bestellen: {n}", it: "In ritardo, ordina ora: {n}", pt: "Atrasado, encomende já: {n}", nl: "Te laat – bestel nu: {n}", pl: "Spóźnione – zamów teraz: {n}" },
  "Lines valued at retail price (no cost in Shopify): {n}": { es: "Líneas valoradas a precio de venta (sin coste en Shopify): {n}", fr: "Lignes valorisées au prix de vente (pas de coût dans Shopify) : {n}", de: "Positionen zum Verkaufspreis bewertet (keine Kosten in Shopify): {n}", it: "Righe valutate a prezzo di vendita (nessun costo in Shopify): {n}", pt: "Linhas valorizadas a preço de venda (sem custo no Shopify): {n}", nl: "Regels gewaardeerd tegen verkoopprijs (geen kostprijs in Shopify): {n}", pl: "Pozycje wycenione po cenie sprzedaży (brak kosztu w Shopify): {n}" },
  "Lines without a cost or price, not counted: {n}": { es: "Líneas sin coste ni precio, no contadas: {n}", fr: "Lignes sans coût ni prix, non comptées : {n}", de: "Positionen ohne Kosten oder Preis, nicht gezählt: {n}", it: "Righe senza costo né prezzo, non conteggiate: {n}", pt: "Linhas sem custo nem preço, não contadas: {n}", nl: "Regels zonder kostprijs of prijs, niet meegeteld: {n}", pl: "Pozycje bez kosztu i ceny, nieliczone: {n}" },
  "Based on: units to order × unit cost from Shopify (retail price when the cost is missing)": { es: "Basado en: unidades a pedir × coste unitario de Shopify (precio de venta si falta el coste)", fr: "Basé sur : unités à commander × coût unitaire dans Shopify (prix de vente si le coût manque)", de: "Basierend auf: zu bestellende Einheiten × Stückkosten aus Shopify (Verkaufspreis, wenn die Kosten fehlen)", it: "Basato su: unità da ordinare × costo unitario da Shopify (prezzo di vendita se manca il costo)", pt: "Baseado em: unidades a encomendar × custo unitário do Shopify (preço de venda quando falta o custo)", nl: "Gebaseerd op: te bestellen stuks × kostprijs per stuk uit Shopify (verkoopprijs als de kostprijs ontbreekt)", pl: "Na podstawie: sztuki do zamówienia × koszt jednostkowy z Shopify (cena sprzedaży, gdy brak kosztu)" },
  "Not enough sales history for these dates yet.": { es: "Aún no hay historial de ventas suficiente para estas fechas.", fr: "Pas encore assez d'historique de ventes pour ces dates.", de: "Für diese Daten gibt es noch nicht genug Verkaufshistorie.", it: "Non c'è ancora abbastanza storico vendite per queste date.", pt: "Ainda não há histórico de vendas suficiente para estas datas.", nl: "Nog niet genoeg verkoopgeschiedenis voor deze data.", pl: "Za mało historii sprzedaży dla tych dat." },
  "Based on: units sold and sales on the same dates last year, all sales channels, {range}": { es: "Basado en: unidades vendidas y ventas en las mismas fechas del año pasado, todos los canales de venta, {range}", fr: "Basé sur : unités vendues et ventes aux mêmes dates l'an dernier, tous canaux de vente, {range}", de: "Basierend auf: verkaufte Einheiten und Umsatz an denselben Daten im Vorjahr, alle Verkaufskanäle, {range}", it: "Basato su: unità vendute e vendite nelle stesse date dell'anno scorso, tutti i canali di vendita, {range}", pt: "Baseado em: unidades vendidas e vendas nas mesmas datas do ano passado, todos os canais de venda, {range}", nl: "Gebaseerd op: verkochte stuks en omzet op dezelfde data vorig jaar, alle verkoopkanalen, {range}", pl: "Na podstawie: sprzedane sztuki i sprzedaż w tych samych dniach rok temu, wszystkie kanały sprzedaży, {range}" },
  "Units sold: {n}": { es: "Unidades vendidas: {n}", fr: "Unités vendues : {n}", de: "Verkaufte Einheiten: {n}", it: "Unità vendute: {n}", pt: "Unidades vendidas: {n}", nl: "Verkochte stuks: {n}", pl: "Sprzedane sztuki: {n}" },
